请对以下 case 进行三维加权评分。

=== case_id ===
Case-26-group-buy-002

=== 用户原始指令 (query.txt) ===
奶茶拼单卡片，能点去付款，显示天气，已经付了几单

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "奶茶拼单卡片，能点去付款，显示天气，已经付了几单",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "milk-tea-group-buy-pay"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称",
            "sampleValue": "青浦区"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          }
        }
      }
    },
    "groupBuy": {
      "paidOrdersText": {
        "type": "string",
        "description": "奶茶拼单中已经完成付款的订单数量展示文本",
        "sampleValue": "3单"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合用于奶茶拼单卡片中的当前天气视觉锚点。"
    }
  ]
}

